import{_ as e,c as r,o as t,ag as o}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"はじめに","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1794112334000}'),i={name:"ja/guide/introduction.md"};function n(s,a,l,h,c,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><h2 id="nicasa-について" tabindex="-1">Nicasa について <a class="header-anchor" href="#nicasa-について" aria-label="Permalink to &quot;Nicasa について&quot;">​</a></h2><p>Nicasa は、スピード・シンプルさ・強力な編集機能を重視して設計された、モダンなデスクトップ画像ビューア兼スクリーンショットツールです。macOS 専用に作られており、滑らかでモダンな画像閲覧体験をデスクトップにもたらします。</p><h2 id="主な機能" tabindex="-1">主な機能 <a class="header-anchor" href="#主な機能" aria-label="Permalink to &quot;主な機能&quot;">​</a></h2><h3 id="🖼️-より良い画像閲覧" tabindex="-1">🖼️ <strong>より良い画像閲覧</strong> <a class="header-anchor" href="#🖼️-より良い画像閲覧" aria-label="Permalink to &quot;🖼️ **より良い画像閲覧**&quot;">​</a></h3><p>クリーンで集中できるインターフェースで画像を一瞬で表示。雑念も乱雑さもなく、開いた瞬間にコンテンツが美しく現れます。</p><h3 id="📸-スクリーンショットとキャプチャ" tabindex="-1">📸 <strong>スクリーンショットとキャプチャ</strong> <a class="header-anchor" href="#📸-スクリーンショットとキャプチャ" aria-label="Permalink to &quot;📸 **スクリーンショットとキャプチャ**&quot;">​</a></h3><p>画面の任意の部分を数秒で撮影。高速で正確なスクリーンショットツールが Nicasa に組み込まれており、ビジュアルアイデアの保存と共有がこれまでになく簡単です。</p><h3 id="🤖-ai-画像エディター" tabindex="-1">🤖 <strong>AI 画像エディター</strong> <a class="header-anchor" href="#🤖-ai-画像エディター" aria-label="Permalink to &quot;🤖 **AI 画像エディター**&quot;">​</a></h3><p>強力な AI ツールで画像を強化・調整。簡単な補正からインテリジェントな編集まで、Nicasa が画像の変化を手軽に実現します。</p><h3 id="🔍-透明オーバーレイモード" tabindex="-1">🔍 <strong>透明オーバーレイモード</strong> <a class="header-anchor" href="#🔍-透明オーバーレイモード" aria-label="Permalink to &quot;🔍 **透明オーバーレイモード**&quot;">​</a></h3><p>デザイナーやアーティストに最適なツール：画像をすべてのウィンドウの最前面に固定し、透明度を調整できます。トレース、参照資料との照合、UI 比較に最適です。</p><h3 id="🌐-chrome-拡張機能との連携" tabindex="-1">🌐 <strong>Chrome 拡張機能との連携</strong> <a class="header-anchor" href="#🌐-chrome-拡張機能との連携" aria-label="Permalink to &quot;🌐 **Chrome 拡張機能との連携**&quot;">​</a></h3><p>Nicasa Chrome 拡張機能とシームレスに連携し、あらゆるウェブサイトの画像を 1 か所で閲覧できます。画像をその場で抽出・閲覧し、Nicasa で直接開けるため、より高速で没入感のある閲覧体験が得られます。</p><h3 id="🎨-滑らかで直感的なデザイン" tabindex="-1">🎨 <strong>滑らかで直感的なデザイン</strong> <a class="header-anchor" href="#🎨-滑らかで直感的なデザイン" aria-label="Permalink to &quot;🎨 **滑らかで直感的なデザイン**&quot;">​</a></h3><p>次世代技術を搭載し、流動的なトランジション、鮮明なレンダリング、細やかな配慮の行き届いたインタラクションを提供します。</p><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to &quot;システム要件&quot;">​</a></h2><ul><li><strong>オペレーティングシステム</strong>：macOS 10.13 以降</li><li><strong>メモリ</strong>：最低 4GB RAM、8GB 推奨</li><li><strong>ストレージ</strong>：インストールに 54.5 MB</li><li><strong>ディスプレイ</strong>：最低 1280x720 の解像度</li></ul><h2 id="対応言語" tabindex="-1">対応言語 <a class="header-anchor" href="#対応言語" aria-label="Permalink to &quot;対応言語&quot;">​</a></h2><p>Nicasa は多言語に対応しています：英語、簡体字中国語、繁体字中国語、日本語、フランス語、韓国語、ドイツ語、スペイン語、イタリア語、ベトナム語、タイ語、ヒンディー語、トルコ語、ロシア語、ポルトガル語、オランダ語、ドイツ語（スイス）、フィンランド語、マレー語、ギリシャ語、ノルウェー語、インドネシア語、ハンガリー語、デンマーク語、ウクライナ語。</p><h2 id="はじめかた" tabindex="-1">はじめかた <a class="header-anchor" href="#はじめかた" aria-label="Permalink to &quot;はじめかた&quot;">​</a></h2><p>Nicasa を初めて使う方は、<a href="/ja/guide/installation.html">インストールガイド</a>から始めて、お使いの Mac でアプリを起動しましょう。</p>',22)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
